#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
pub struct ContractVersions {
    pub internal_protocol: u16,
    pub center_store: u32,
    pub host_store: i64,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(into = "u64")]
// The field remains private: every public construction and deserialization
// goes through TryFrom. A plain integer avoids the fixed extractor's unsupported
// NonZero associated-type representation without changing the wire contract.
pub struct PositiveCounter(u64);

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ProbeRequest {
    pub protocol_version: u16,
    pub node: NodeIdentity,
    /// Correlates this read-only call; not a persisted lifecycle operation.
    pub request_id: OperationId,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Intent {
    Create,
    /// Already normalized against the ORIGINAL lifetime, never retry-now + duration.
    Renew {
        end_at_ms: u64,
    },
    Destroy,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LifecycleRequest {
    pub identity: ControlIdentity,
    /// Every operation carries the original binding, including destroy-first.
    pub create: CreateBinding,
    pub intent: Intent,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum LifecycleFact {
    /// Durable inbox only; neither VM admission nor success.
    Recorded,
    Ready {
        started_at_ms: u64,
        end_at_ms: u64,
        max_end_at_ms: u64,
    },
    Renewed {
        end_at_ms: u64,
    },
    /// Original VM stopped, but quota is still held until exact cleanup.
    Stopped,
    Cleaned,
    /// ONLY before local admission, with no local effects/responsibility.
    NotAccepted,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct WindowCloseRequest {
    pub terminal: LifecycleResponse,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct WindowCloseAck {
    pub terminal: LifecycleResponse,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct StatusRequest {
    pub node: NodeIdentity,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct HostStatus {
    pub node: NodeIdentity,
    /// Protected inbox capacity, not inferred from native IDs or physical slots.
    pub retention_slots: u16,
    pub observed_at_ms: u64,
    /// Conservative physical/local free capacity. It can only veto admission;
    /// center reservations are still counted separately by the pure core.
    pub free: Resources,
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ReadinessRequest {
    pub node: NodeIdentity,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CacheRequest {
    pub node: NodeIdentity,
    pub revision: ResourceId,
    pub digest: [u8; 32],
    /// Original global descriptor only. The receiver derives local cache paths
    /// from its protected root; these descriptor paths are NEVER write targets.
    pub descriptor: TemplateBinding,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ArtifactPart {
    Kernel,
    Rootfs,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ValidationRequest {
    pub create: ControlIdentity,
    pub terminal: ControlIdentity,
    pub revision: ResourceId,
    /// Initial center-accepted build metadata. No caller local IDs, checked
    /// flag or certificate may be supplied, and its paths are never executed.
    pub publication: Publication,
}
